head.b:skin:
/* AMAROV007 — dark glass theme v2 (visual effects + official data) */
:root{--bg:#05070B;--card:rgba(13,18,28,.7);--line:rgba(255,255,255,.08);--cy:#00D2FF;--tx:#E8EEF7;--mu:#8A97AB;--bl:#2A8CFF}
*{box-sizing:border-box;margin:0}
html{scroll-behavior:smooth;scroll-padding-top:80px}
body{background:var(--bg);color:var(--tx);font-family:'Tajawal',Inter,sans-serif;line-height:1.7;overflow-x:hidden;position:relative}
body:before{content:"";position:fixed;inset:0;z-index:-2;background:radial-gradient(rgba(255,255,255,.12) 1px,transparent 1px) 0 0/26px 26px;-webkit-mask-image:linear-gradient(#000,transparent 85%);mask-image:linear-gradient(#000,transparent 85%)}
body:after{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(60% 40% at 50% -5%,rgba(0,210,255,.16),transparent 70%),radial-gradient(35% 35% at 100% 40%,rgba(60,70,220,.18),transparent 70%),radial-gradient(35% 35% at 0 80%,rgba(0,210,255,.08),transparent 70%)}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
.num{font-family:'JetBrains Mono','Inter',monospace;direction:ltr;unicode-bidi:isolate}
.wrap{max-width:1160px;margin:auto;padding:0 20px}
section{padding:72px 0}
/* hide Blogger navbar for everyone */
#navbar,#navbar-iframe,.navbar,#Navbar1{display:none!important;height:0!important;visibility:hidden!important}
/* aurora + progress */
.aur{position:fixed;inset:0;z-index:-1;pointer-events:none;overflow:hidden}
.aur i{position:absolute;width:46vmax;height:46vmax;border-radius:50%;filter:blur(90px);opacity:.28;will-change:transform}
.aur i:nth-child(1){background:#1769E8;top:-18vmax;inset-inline-start:-10vmax;animation:dr1 26s ease-in-out infinite alternate}
.aur i:nth-child(2){background:#00A9D6;bottom:-24vmax;inset-inline-end:-12vmax;animation:dr2 32s ease-in-out infinite alternate}
@keyframes dr1{to{transform:translate(18vmax,12vmax) scale(1.15)}}
@keyframes dr2{to{transform:translate(-16vmax,-10vmax) scale(1.2)}}
#sp{position:fixed;top:0;inset-inline-start:0;height:3px;width:0;z-index:200;background:linear-gradient(90deg,var(--cy),var(--bl));box-shadow:0 0 12px var(--cy)}
/* reveal */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .8s cubic-bezier(.2,.7,.2,1),transform .8s cubic-bezier(.2,.7,.2,1)}
.js .rv.in{opacity:1;transform:none}
@keyframes fu{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.glass{position:relative;overflow:hidden;background:var(--card);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);border:1px solid var(--line);border-radius:16px;transition:border-color .25s,box-shadow .25s,transform .25s}
.glass:hover{border-color:rgba(0,210,255,.35);box-shadow:inset 0 0 30px rgba(0,210,255,.06)}
.glass:after{content:"";position:absolute;inset:0;pointer-events:none;opacity:0;transition:opacity .3s;background:radial-gradient(260px circle at var(--mx,50%) var(--my,50%),rgba(0,210,255,.13),transparent 70%)}
.glass:hover:after{opacity:1}
.pill{display:inline-block;font-size:12px;padding:3px 12px;border:1px solid var(--line);border-radius:99px;color:var(--mu);background:rgba(255,255,255,.03)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 22px;border-radius:10px;border:1px solid var(--line);background:transparent;color:var(--tx);font:600 14px Tajawal;cursor:pointer;transition:.2s}
.btn:hover{border-color:rgba(0,210,255,.5);transform:translateY(-1px)}
.btn.p{background:linear-gradient(#2A8CFF,#1769E8);border-color:#3C98FF;box-shadow:0 0 24px rgba(30,120,255,.35)}
.btn.p:hover{box-shadow:0 0 34px rgba(30,120,255,.6)}
h1{font-size:clamp(32px,6vw,58px);line-height:1.2;font-weight:800;letter-spacing:-.5px}
h2{font-size:clamp(24px,4vw,36px);font-weight:700;text-align:center}
.sub{color:var(--mu);text-align:center;max-width:640px;margin:10px auto 36px}
/* logo chips */
.lg{width:44px;height:44px;flex:none;border-radius:12px;background:#fff;display:grid;place-items:center;overflow:hidden;box-shadow:0 0 0 1px rgba(255,255,255,.1),0 6px 18px -6px rgba(0,0,0,.6)}
.lg img{width:30px;height:30px;object-fit:contain}
.lg i{font:700 18px Inter;color:#0B1019;font-style:normal}
.lg.s{width:28px;height:28px;border-radius:8px}.lg.s img{width:20px;height:20px}.lg.s i{font-size:13px}
.lg.l{width:60px;height:60px;border-radius:16px}.lg.l img{width:42px;height:42px}
/* promo + header */
#promo{display:flex;gap:12px;justify-content:center;align-items:center;flex-wrap:wrap;padding:9px 16px;font-size:14px;background:rgba(0,210,255,.07);border-bottom:1px solid var(--line)}
#promo button{font:700 13px 'JetBrains Mono';padding:3px 12px;border-radius:8px;border:1px dashed var(--cy);background:none;color:var(--cy);cursor:pointer}
header{position:sticky;top:0;z-index:50;background:rgba(5,7,11,.7);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);border-bottom:1px solid var(--line);box-shadow:0 1px 0 rgba(42,110,255,.28),0 8px 30px -18px rgba(42,110,255,.6)}
header .wrap{display:flex;align-items:center;justify-content:space-between;height:64px}
.logo{font:700 19px Inter;display:flex;gap:8px;align-items:center}
.logo i{width:22px;height:22px;border-radius:7px;background:conic-gradient(from 200deg,#1769E8,var(--cy),#1769E8);animation:spin 8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
nav{display:flex;gap:24px;font-size:15px;color:var(--mu)}
nav a{position:relative;transition:color .2s}
nav a:after{content:"";position:absolute;inset-inline:0;bottom:-4px;height:2px;background:var(--cy);transform:scaleX(0);transition:transform .25s}
nav a:hover{color:var(--tx)}nav a:hover:after{transform:scaleX(1)}
#burger{display:none;background:none;border:1px solid var(--line);color:var(--tx);border-radius:8px;padding:6px 10px;font-size:18px}
@media(max-width:900px){nav{display:none;position:absolute;top:64px;inset-inline:0;flex-direction:column;background:#080B11;padding:18px 24px;border-bottom:1px solid var(--line)}nav.open{display:flex}#burger{display:block}}
/* hero */
.hero{position:relative;isolation:isolate;padding:70px 0 20px}
#fx{position:absolute;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none;-webkit-mask-image:linear-gradient(#000 40%,transparent);mask-image:linear-gradient(#000 40%,transparent)}
.hero:before{content:"";position:absolute;left:50%;bottom:-120px;width:min(900px,100%);height:260px;transform:translateX(-50%);border-radius:0 0 50% 50%/0 0 100% 100%;background:radial-gradient(ellipse at 50% 100%,rgba(42,110,255,.75),rgba(30,70,200,.25) 45%,transparent 70%);filter:blur(34px);pointer-events:none;z-index:-1}
.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:44px;align-items:center}
.hero-t{text-align:start}
.hero-t h1{font-size:clamp(28px,4.4vw,48px);background:linear-gradient(#fff,#BFD4FF);-webkit-background-clip:text;background-clip:text;color:transparent;margin-top:18px}
.hero-t p{color:var(--mu);max-width:560px;margin:18px 0 28px;font-size:18px}
.acts{display:flex;gap:8px;flex-wrap:wrap}
.rate{display:inline-flex;align-items:center;gap:10px;padding:6px 14px;border:1px solid rgba(60,120,255,.35);border-radius:99px;background:rgba(10,18,40,.6);font-size:13px;color:var(--mu);flex-wrap:wrap}
.rate .st{color:#3C98FF;letter-spacing:2px}
.rate b{font:600 13px 'JetBrains Mono';color:var(--tx)}
.hv{position:relative;width:100%;max-width:400px;margin-inline:auto;perspective:900px}
.hvi{position:relative;border-radius:26px;overflow:hidden;border:1px solid rgba(60,120,255,.35);box-shadow:0 0 0 1px rgba(255,255,255,.04),0 30px 80px -20px rgba(30,100,255,.55);transform:rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));transition:transform .2s;aspect-ratio:9/15}
.hvi img{width:100%;height:100%;object-fit:cover;object-position:50% 20%}
.hvi:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 60%,rgba(5,7,11,.8))}
.chip{position:absolute;font:700 12px 'JetBrains Mono';direction:ltr;padding:6px 12px;border-radius:99px;background:rgba(5,10,20,.78);border:1px solid;-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);animation:fl 5s ease-in-out infinite}
.c1{top:12%;inset-inline-start:-14px;color:#4ade80;border-color:rgba(74,222,128,.5)}
.c2{top:46%;inset-inline-end:-14px;color:#ff6b6b;border-color:rgba(255,107,107,.5);animation-delay:-1.6s}
.c3{bottom:9%;inset-inline-start:-10px;color:var(--cy);border-color:rgba(0,210,255,.5);animation-delay:-3s}
@keyframes fl{50%{transform:translateY(-10px)}}
.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:56px}
.metrics .glass{padding:22px}.metrics b{display:block;font:700 26px 'JetBrains Mono';color:var(--cy)}.metrics span.t{color:var(--mu);font-size:14px}
@media(max-width:900px){.hero-grid{grid-template-columns:1fr;gap:34px}.hv{max-width:320px}.metrics{grid-template-columns:1fr 1fr}.c1{inset-inline-start:-6px}.c2{inset-inline-end:-6px}}
@media(max-width:520px){.metrics{grid-template-columns:1fr}}
/* ticker */
.tk{border-block:1px solid var(--line);overflow:hidden;direction:ltr;background:rgba(255,255,255,.015);padding:12px 0;margin-top:40px}
.tk div{display:flex;gap:40px;width:max-content;animation:mq 42s linear infinite;font:600 13px 'JetBrains Mono';color:var(--mu);white-space:nowrap}
.tk b{color:var(--tx)}.tk em{color:var(--cy);font-style:normal}
@keyframes mq{to{transform:translateX(-50%)}}
/* filter + cards */
.sizes{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-bottom:28px}
.sizes button{font:600 14px 'JetBrains Mono';padding:8px 18px;border-radius:99px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--mu);cursor:pointer;transition:.2s}
.sizes button:hover{color:var(--tx)}
.sizes button.on{color:#fff;border-color:rgba(0,210,255,.5);background:rgba(0,210,255,.1)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));gap:16px}
.fc{padding:22px;display:flex;flex-direction:column;gap:14px;animation:fu .5s both}
.fc:hover{transform:translateY(-4px)}
.fc.off{opacity:.45}
.fc h3{font-size:20px}
.fh{display:flex;align-items:center;gap:12px}
.price{font:700 34px 'JetBrains Mono';text-align:right;direction:ltr}
.price small{display:block;font:500 12px Tajawal;color:var(--mu);direction:rtl;text-align:right}
.rows div{display:flex;justify-content:space-between;gap:10px;font-size:14px;padding:6px 0;border-bottom:1px solid var(--line)}
.rows span{color:var(--mu);flex:none}.rows b{font-weight:500;text-align:left}
.tags{display:flex;flex-wrap:wrap;gap:6px}
.code{font:700 12px 'JetBrains Mono';color:var(--cy);border:1px dashed rgba(0,210,255,.5);padding:3px 10px;border-radius:8px;background:none;cursor:pointer}
.cn{font-size:13px;color:var(--mu)}
.pill,.rows b,td,.fr2 b,.price small{unicode-bidi:plaintext}
.fc .btn{white-space:nowrap;padding:10px 16px}
.fc .fb{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-top:auto}
/* official profiles */
.ptabs{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-bottom:22px}
.ptabs button{display:flex;align-items:center;gap:8px;padding:7px 16px 7px 12px;border-radius:99px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--mu);font:600 14px Tajawal;cursor:pointer;transition:.2s}
.ptabs button.on{color:#fff;border-color:rgba(0,210,255,.5);background:rgba(0,210,255,.1)}
.pbody{padding:28px}
.ph{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:12px}
.fr2{display:grid;grid-template-columns:210px 1fr;gap:6px 18px;padding:12px 0;border-bottom:1px solid var(--line);font-size:14px}
.fr2 b{color:var(--cy);font-weight:600}.fr2 span{color:var(--tx)}
@media(max-width:700px){.fr2{grid-template-columns:1fr}.pbody{padding:20px}}
.lks{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}
.lks a{font-size:13px;padding:6px 14px;border:1px solid rgba(0,210,255,.3);border-radius:99px;color:var(--cy);transition:.2s}
.lks a:hover{background:rgba(0,210,255,.1)}
.rev{color:var(--mu);font-size:12px;margin-top:14px}
/* risk banner (warrior) */
.wb{position:relative;border-radius:26px;overflow:hidden;display:grid;grid-template-columns:1.1fr .9fr;border:1px solid var(--line);background:rgba(8,12,20,.6)}
.wbi{position:relative;min-height:600px;overflow:hidden}
.wbi img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 42%;animation:kb 26s ease-in-out infinite alternate}
.wbi:before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(270deg,rgba(8,12,20,.95) 0%,transparent 38%)}
@keyframes kb{from{transform:scale(1)}to{transform:scale(1.08)}}
.wbc{padding:44px;align-self:center}
.wbc h2{text-align:start;margin-bottom:10px}
.wbc>p{color:var(--mu);margin-bottom:22px}
.rk{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.rk .glass{padding:16px}.rk b{display:block;color:var(--cy);font-size:15px;margin-bottom:4px}.rk span{font-size:13px;color:var(--mu);display:block}.rk em{font-style:normal;font-size:11px;color:#6f7d94}
@media(max-width:860px){.wb{grid-template-columns:1fr}.wbi{min-height:360px;order:-1}.wbi:before{background:linear-gradient(0deg,rgba(8,12,20,.95) 0%,transparent 45%)}.wbc{padding:26px 20px}.rk{grid-template-columns:1fr}}
/* calc */
.calc{display:grid;grid-template-columns:1.2fr 1fr;gap:16px}
.calc .glass{padding:26px}
.sl{margin-bottom:22px}.sl label{display:flex;justify-content:space-between;font-size:14px;color:var(--mu);margin-bottom:8px}
input[type=range]{width:100%;accent-color:#2A8CFF}
.out b{display:block;font:700 38px 'JetBrains Mono';direction:ltr;text-align:right}
@media(max-width:760px){.calc{grid-template-columns:1fr}}
/* table + guide + faq */
.tw{overflow-x:auto;-webkit-overflow-scrolling:touch;padding:0}
table{width:100%;min-width:980px;border-collapse:collapse;font-size:14px}
th,td{padding:14px 16px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}
th{color:var(--mu);font-weight:500}
.gl{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}
.gl .glass{padding:20px}.gl h3{font-size:17px;margin-bottom:6px;color:var(--cy)}.gl p{color:var(--mu);font-size:14px}
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;counter-reset:s;margin-top:40px}
.steps .glass{padding:54px 22px 22px;counter-increment:s}
.steps .glass:before{content:counter(s);position:absolute;top:16px;inset-inline-start:20px;width:30px;height:30px;border-radius:50%;background:linear-gradient(#2A8CFF,#1769E8);font:700 14px 'JetBrains Mono';display:grid;place-items:center;box-shadow:0 0 18px rgba(30,120,255,.5)}
.steps h3{font-size:16px;margin-bottom:4px}.steps p{color:var(--mu);font-size:14px}
.faq{max-width:760px;margin:auto;display:grid;gap:10px}
.faq details{padding:0 20px}.faq summary{cursor:pointer;list-style:none;padding:16px 0;display:flex;justify-content:space-between;gap:12px;font-weight:600}
.faq summary::-webkit-details-marker{display:none}
.faq summary:after{content:"+";width:22px;height:22px;flex:none;border-radius:50%;background:#1769E8;text-align:center;line-height:22px;transition:transform .25s}
.faq details[open] summary:after{transform:rotate(45deg)}
.faq p{color:var(--mu);padding-bottom:16px}
/* CTA (chess) */
.cta{display:grid;grid-template-columns:1.1fr .9fr;align-items:stretch}
.cta .ct{padding:42px;display:flex;flex-direction:column;justify-content:center;gap:14px}
.cta .ct h2{text-align:start}.cta .ct p{color:var(--mu)}
.cta .ci{position:relative;min-height:340px}
.cta .ci img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.cta .ci:before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(270deg,var(--bg),transparent 45%)}
@media(max-width:760px){.cta{grid-template-columns:1fr}.cta .ci{min-height:260px;order:-1}.cta .ci:before{background:linear-gradient(0deg,var(--bg),transparent 50%)}.cta .ct{padding:26px 20px}}
/* sources */
.src{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}
.src .glass{padding:18px}.src h3{font-size:16px;display:flex;align-items:center;gap:10px;margin-bottom:8px}
.src a{display:block;font-size:13px;color:var(--cy);padding:3px 0;overflow-wrap:anywhere}
/* footer + modal */
footer{border-top:1px solid var(--line);padding:40px 0;color:var(--mu);font-size:13px}
footer .risk{padding:18px;margin-bottom:22px;line-height:1.9}
#cr{cursor:default;user-select:none;-webkit-user-select:none}
.modal{position:fixed;inset:0;z-index:100;background:rgba(0,0,0,.7);display:none;align-items:center;justify-content:center;padding:16px}
.modal.on{display:flex}
.box{width:100%;max-width:440px;padding:26px;background:#0B1019}
.box.big{max-width:760px;max-height:90vh;overflow:auto}
input[type=password],input[type=text],textarea{width:100%;background:rgba(255,255,255,.04);border:1px solid var(--line);color:var(--tx);border-radius:10px;padding:11px;font:14px 'JetBrains Mono';margin:10px 0;direction:ltr}
textarea{min-height:300px;resize:vertical}
.blogwrap{max-width:820px;margin:40px auto;padding:0 20px}
.blogwrap .post-title{font-size:30px}
.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}
.fgrid label{font-size:12px;color:var(--mu);display:block}
.fgrid .w{grid-column:1/-1}
select{width:100%;background:#0B1019;color:var(--tx);border:1px solid var(--line);border-radius:10px;padding:10px;font:14px Tajawal}
details.adv summary{cursor:pointer;color:var(--mu);font-size:13px;margin:14px 0 4px}
@media(max-width:560px){.fgrid{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv{opacity:1;transform:none}}

body.script:
