function tilt(){var hv=$('hv');if(!hv||RM||!window.matchMedia||!matchMedia('(hover:hover)').matches)return;var hi=hv.firstElementChild;
 hv.addEventListener('pointermove',function(e){var r=hv.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;hi.style.setProperty('--ry',(x*10)+'deg');hi.style.setProperty('--rx',(-y*10)+'deg')});
 hv.addEventListener('pointerleave',function(){hi.style.setProperty('--rx','0deg');hi.style.setProperty('--ry','0deg')})}
document.addEventListener('pointermove',function(e){var g=e.target.closest&&e.target.closest('.glass');if(g){var r=g.getBoundingClientRect();g.style.setProperty('--mx',(e.clientX-r.left)+'px');g.style.setProperty('--my',(e.clientY-r.top)+'px')}},{passive:true});
var sp=$('sp'),tk=false;
window.addEventListener('scroll',function(){if(tk)return;tk=true;requestAnimationFrame(function(){var h=document.documentElement.scrollHeight-window.innerHeight;sp.style.width=(h>0?Math.min(100,window.scrollY/h*100):0)+'%';tk=false})},{passive:true});
/* hidden admin: open with #admin, Alt+Shift+A, or 7 quick taps on the copyright line */
function pin(){try{return localStorage.getItem(PK)||'007007'}catch(e){return '007007'}}
function open(id){$(id).classList.add('on')}
function close(id){$(id).classList.remove('on')}
document.querySelectorAll('[data-close]').forEach(function(b){b.onclick=function(){close(b.dataset.close)}});
function askPin(){$('pin').value='';$('pinE').textContent='';open('pinM');setTimeout(function(){$('pin').focus()},50)}
if(location.hash==='#admin')askPin();
window.addEventListener('hashchange',function(){if(location.hash==='#admin')askPin()});
document.addEventListener('keydown',function(e){if(e.altKey&&e.shiftKey&&e.code==='KeyA'){e.preventDefault();askPin()}});
var taps=0,tt;$('cr').addEventListener('click',function(){taps++;clearTimeout(tt);tt=setTimeout(function(){taps=0},2500);if(taps>=7){taps=0;askPin()}});
function enter(){if($('pin').value===pin()){close('pinM');fill();$('msg').textContent='';open('admM')}else $('pinE').textContent='PIN غير صحيح'}
$('pinOk').onclick=enter;$('pin').onkeydown=function(e){if(e.key==='Enter')enter()};
var FL=[['name','الاسم'],['domain','نطاق الشعار (domain)'],['models','النماذج'],['code','كود الخصم'],['link','رابط الإحالة / الشراء','w'],['site','الموقع الرسمي','w'],['prices','الأسعار (حجم:سعر) مثال 10:60,50:239','w'],['from','نص السعر البديل'],['priceNote','ملاحظة السعر'],['target','هدف الربح'],['daily','السحب اليومي'],['max','أقصى سحب'],['split','تقسيم الأرباح'],['payout','السحوبات'],['lev','الرافعة'],['news','الأخبار'],['platforms','المنصات (مفصولة بفاصلة)','w'],['extra','ملاحظة سعر إضافية','w'],['note','ملاحظة','w']];
var idx=0;
function pstr(o){return Object.keys(o||{}).map(function(k){return k+':'+o[k]}).join(',')}
function pobj(t){var o={};String(t).split(',').forEach(function(x){var q=x.split(':');if(q.length==2&&q[0].trim()&&!isNaN(+q[1]))o[q[0].trim()]=+q[1]});return o}
function fill(){var sl=$('sel');sl.innerHTML=F.map(function(f,i){return '<option value="'+i+'">'+esc(f.name)+'</option>'}).join('');if(idx>=F.length)idx=0;sl.value=idx;
 var f=F[idx]||{};$('ff').innerHTML=FL.map(function(x){var v=x[0]=='prices'?pstr(f.prices):x[0]=='platforms'?(f.platforms||[]).join(','):(f[x[0]]||'');return '<div class="'+(x[2]||'')+'"><label>'+x[1]+'</label><input type="text" data-k="'+x[0]+'" value="'+esc(v)+'"/></div>'}).join('');$('ed').value=JSON.stringify(F,null,2)}
$('sel').onchange=function(){idx=+$('sel').value;fill()};
$('sf').onclick=function(){var f=F[idx];if(!f)return;document.querySelectorAll('#ff input').forEach(function(i){var k=i.dataset.k,v=i.value.trim();if(k=='prices')f.prices=pobj(v);else if(k=='platforms')f.platforms=v?v.split(',').map(function(x){return x.trim()}):[];else f[k]=v});render();fill();$('msg').textContent='تم التطبيق. اضغط حفظ الكل لتثبيته.'};
$('nf').onclick=function(){F.push({id:'f'+Date.now(),name:'شركة جديدة',domain:'',site:'https://',code:AFF,link:'https://',models:'2-Step',prices:{},target:'8% / 5%',daily:'5%',max:'10%',split:'80%',payout:'أسبوعي',lev:'1:100',news:'',platforms:['cTrader'],facts:[],links:[]});idx=F.length-1;render();fill()};
$('df').onclick=function(){if(F[idx]&&confirm('حذف '+F[idx].name+'؟')){F.splice(idx,1);idx=0;render();fill()}};
$('sv').onclick=function(){try{var t=$('ed').value;var d=JSON.parse(t);if(!Array.isArray(d))throw 0;F=d;localStorage.setItem(K,JSON.stringify(d));render();fill();$('msg').textContent='تم الحفظ في هذا المتصفح.'}catch(e){$('msg').textContent='JSON غير صالح أو التخزين غير متاح.'}};
$('ex').onclick=function(){copy($('ed').value,$('ex'))};
$('rs').onclick=function(){if(confirm('استعادة البيانات الافتراضية؟')){try{localStorage.removeItem(K)}catch(e){}F=JSON.parse(JSON.stringify(DEF));idx=0;render();fill()}};
$('cp').onclick=function(){var n=prompt('PIN جديد (4 أرقام على الأقل):');if(n&&n.length>=4){try{localStorage.setItem(PK,n);$('msg').textContent='تم تغيير PIN.'}catch(e){}}};
render();calc();reveal();counters();candles();tilt();
window.__ok=1;
})();
